cat > .shots/sheet.gd <<'EOF'
extends SceneTree
func _init() -> void:
	var dir := "res://.shots"
	var files: Array = []
	for f in DirAccess.get_files_at(dir):
		if f.begins_with("shot_") and f.ends_with(".png"):
			files.append(f)
	files.sort()
	var per := 6
	var n := 0
	for s in range(0, files.size(), per):
		var sheet := Image.create(1280, 1080, false, Image.FORMAT_RGBA8)
		for k in per:
			if s + k >= files.size():
				break
			var im := Image.load_from_file(ProjectSettings.globalize_path(dir + "/" + files[s + k]))
			im.convert(Image.FORMAT_RGBA8)
			im.resize(640, 360, Image.INTERPOLATE_LANCZOS)
			sheet.blit_rect(im, Rect2i(0, 0, 640, 360), Vector2i((k % 2) * 640, (k / 2) * 360))
		n += 1
		sheet.save_png(ProjectSettings.globalize_path(dir + "/sheet_%02d.png" % n))
	quit()
EOF
godot --headless --path . -s .shots/sheet.gd 2>&1 | grep -iE "error" ; ls .shots | grep sheet
